      "bio": "마왕성의 살림과 피난민 숙소를 혼자 꾸려 가는 집사. 손님이 말하기 전에 필요한 것을 먼저 챙기고, 누구에게나 다정하고 정중하다. 혈액은 계약한 공급처에서만 정중하게 사 온다. 사망자 명부의 빈칸을 가장 싫어한다.",
