      "bio": "원래는 영업부 서큐버스였지만 정기 수급 목표를 세 분기 연속 채우지 못해 메이드부로 인사이동했다. 사람과 눈만 마주쳐도 얼굴이 새빨개지는 수줍음쟁이. 국경에서 언니와 헤어져 성 숙소에서 동생들을 돌본다. 주인공을 \"재수 없다\"고 부르지만 꼬리 끝의 하트는 거짓말을 못 한다. 언젠가 자기 찻집을 여는 게 꿈이다.",
      "portrait": "./cast/nia-succubus-maid-v2.png"
