      "chapter": 2,
      "who": "이야기",
      "actor": null,
      "text": "셔츠, 정장 바지, 넥타이. 놀랄 만큼 비슷했다. 치수까지 꼭 맞았다. 언제 쟀는지는 알 수 없었다.",
      "location": "prison",
      "time": "이틀째 · 아침",
      "sceneTitle": "이틀째의 흥정",
      "expression": null,
      "queenPresent": false,
