      "chapter": 2,
      "who": "이야기",
      "actor": null,
      "text": "끝으로 갈수록 연보랏빛이 번지는 은백색 머리카락, 이마 위에서 깃털처럼 흔들리는 더듬이 두 가닥, 속눈썹 끝에 내려앉은 은가루. 꿀처럼 달콤한 목소리였는데, 이상하게도 들을수록 등줄기가 서늘해졌다.",
      "location": "prison",
