      "text": "목소리의 주인은 의자 위에 올라서 있었다. 뜻밖에도 작은 여자였다. 발목까지 흘러내리는 노란 머리를 양 갈래로 묶었고, 그 사이로 검은 외뿔 하나가 솟아 있었다. 한쪽 팔은 팔꿈치 아래로 붉은 용비늘, 등 뒤에서는 금빛 비늘 꼬리가 바닥을 탁, 탁 내리치고 있었다. 의자 옆에는 그녀 키보다 큰 도끼가 기대어 있었다.",
