    "ensemble-8-0": {
      "id": "ensemble-8-0",
      "chapter": 8,
      "who": "이야기",
      "actor": null,
      "text": "1막 「죽지 않는 남자」 끝\n\n여드레째 아침. 붉은 달까지 D-93.\n\n교단은 그가 몇 번이든 살아난다는 걸 알고 있었다. 마왕은 100일이라는 숫자를 우연이 아니게 골랐다. 그리고 비어 있던 네 번째 의자에는, 처음부터 누군가 앉아 있었다.\n\n2막 「마왕의 100일」은 준비 중입니다.",
      "location": "balcony",
      "time": "여드레째 · 아침",
      "sceneTitle": "2막 예고",
      "expression": null,
      "queenPresent": false,
      "next": "story-9-entry",
      "displayActor": null,
      "present": []
    },
    "ensemble-9-0": {
      "id": "ensemble-9-0",
      "chapter": 9,
      "who": "이야기",
      "actor": null,
      "text": "요즘 들어 이상하게 한기가 느껴졌다. 잘 때도, 밥을 먹을 때도, 심지어 샤워를 할 때도.",
      "location": "bedroom",
      "time": "마흔째 · 새벽",
      "sceneTitle": "마흔째의 한기",
      "expression": null,
      "queenPresent": false,
      "next": "v5-9-1",
      "displayActor": null,
      "present": []
    },
    "v5-9-1": {
      "id": "v5-9-1",
      "chapter": 9,
      "who": "이야기",
      "actor": null,
      "text": "처음에는 돌바닥 탓이라고 생각했다. 그다음엔 창문 틈 탓. 그런데 한기는 날이 갈수록 또렷해졌다. 언제나 같은 자리, 가슴 위쪽에서부터 천천히 내려앉는 차가움.",
      "location": "bedroom",
      "time": "마흔째 · 새벽",
      "sceneTitle": "마흔째의 한기",
      "expression": null,
      "queenPresent": false,
      "next": "v5-9-2",
      "displayActor": null,
      "present": []
    },
