      "chapter": 9,
      "who": "이야기",
      "actor": null,
      "text": "그 말이 끝나기도 전에 가슴팍이 무거워졌다. 정말로 무언가가 올라타 있었다.",
      "location": "bedroom",
      "time": "마흔째 · 새벽",
      "sceneTitle": "마흔째의 한기",
