      "text": "여자는 소매로 입을 가리고 킥킥 웃다가, 긴 손가락으로 침대 맞은편 마룻바닥을 가리켰다. 지금껏 장식인 줄 알았던 바닥문이 저 혼자 달칵, 하고 열렸다 닫혔다.",
