      "who": "네브라",
      "actor": "N",
      "text": "그게 그거면 어떠냐. 덕분에 나는 너에 대해 모르는 게 없는데. 키킥. 예를 들면, 너 아침마다 거울 보고 “오늘은 안 죽는다” 세 번 중얼거리잖냐.",
