      "who": "네브라",
      "actor": "N",
      "text": "나는 알지. 넥타이는 꼭 두 번 풀었다가 다시 매고, 생각할 때는 엄지로 입술을 꾹 누르고, 자다가 “네, 금요일까지 하겠습니다” 하고 대답하는 것도. 어젯밤엔 두 번 했다. 키킥.",
