      "actor": null,
      "text": "네브라는 이불에 얼굴을 비비며 반쯤 가라앉았다. 이빨 사이로 킥킥 소리가 새어 나왔고, 차가운 바람이 방 안을 한 바퀴 돌고 지나갔다.",
      "location": "bedroom",
      "time": "마흔째 · 새벽",
