  "openingChoices": {
    "revive-three": {
      "0": "“이건 사랑의 힘이라고요!”"
    },
    "intent": {
      "0": "“이 손 좀 보세요. 칼은커녕 키보드 말고는 들어본 적도 없어요.”",
      "1": "“일단 말로 하시죠. 대화해 보면 저 꽤 괜찮은 사람인데.”",
      "2": "“계속 이러시면 저도 용사 할 거예요. 진짜로요. 이력서에 한 줄 추가하죠, 뭐.”"
    }
  },
  "romanceCast": [
    "C",
    "V",
    "N",
    "H",
    "E",
    "R",
    "M"
  ],
  "epilogues": {
    "C": "니아의 찻집은 주말마다 줄이 선다. 창가 자리 하나는 늘 비워둔다. “단골 자리야. 정가 받을 거지만.”",
    "V": "세레인의 관찰 일지는 결국 한 권을 더 채웠다. 마지막 장에는 이렇게 적혀 있다. “결론: 위험함. 계속 관찰 요망.”",
    "N": "네브라는 이제 벽 속에 숨지도 않는다. 당신이 지나가면 어디선가 키킥 소리가 나고, 어느새 어깨 위가 서늘하다. 오늘 아침 당신이 뭐라고 중얼거렸는지는, 이미 알고 있다.",
    "H": "루나엘의 보고서는 왕국에서 화제가 됐다. 마지막 줄이 특히. “마왕성의 인간은 위험하지 않음. 다만 말솜씨가 위험함.”",
    "E": "엘라는 지금도 당신을 “수법쟁이”라고 부른다. 그런데 국경 표지판 하나에, 당신 이름이 작게 새겨져 있다.",
    "R": "이리스의 진료 기록에는 당신 이름 옆에 이렇게 적혀 있다. “미납: 차 한 잔. 영원히 받지 않을 예정.”",
    "M": "로네는 마왕성 회의실 의자 중 하나를 자기 낮잠 자리로 정했다. 당신 옆자리다."
  },
  "redMoonDay": 101,
